style.css:
@-moz-document domain("roblox.com") {
/* ? Fundo animado */
  html, body {
    background: url("https://i.pinimg.com/originals/b9/a7/15/b9a715c3c3ccd918fbd6b75f9e8c92c8.gif") no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    color: #333 !important;
  }

  /* ? Remove fundos brancos que cobrem o GIF */
  .content, .container, .main-content, .rbx-body,
  .game-page, .page-content, .content-container,
  .section, .container-section, .game-home-page,
  .games-list-container, .games-list, .games-list-row,
  .profile-container, .avatar-container, .inventory-container {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* ? Texto padrão */
  * {
    color: #333 !important;
  }

  /* ? Barra superior */
  .navbar, .nav-container, .navigation-container {
    background-color: #ffd6e7 !important;
    border-bottom: 2px solid #ffb6d5 !important;
  }

  .navbar a, .nav-item, .nav-text {
    color: #4a4a4a !important;
  }

  /* ? Barra lateral */
  .left-col, .menu, .side-menu {
    background-color: #ffeaf2 !important;
    color: #4a4a4a !important;
  }

  .menu a, .menu-item a {
    color: #4a4a4a !important;
    border-radius: 8px !important;
  }

  .menu a:hover, .menu-item:hover {
    background-color: #ffcfe1 !important;
    color: #333 !important;
  }

  /* ? TODOS os botões — principais, secundários, menus, ações, etc. */
  button, 
  .btn, 
  .rbx-btn-primary, 
  .rbx-btn-secondary, 
  .btn-common,
  .btn-control,
  .action-button,
  .menu-button,
  .nav-button,
  .game-button,
  .pagination-button,
  .btn-generic,
  .btn-primary,
  .btn-secondary,
  .btn-fixed-width,
  .theme-btn,
  .modal-button,
  .confirm-btn,
  .cancel-btn {
    background-color: #ffb6d5 !important; /* rosa bebê */
    color: #ffffff !important;
    border: none !important;
    border-radius: 10px !important;
    transition: all 0.3s ease !important;
    text-shadow: none !important;
  }

  /* ? Efeito hover (ao passar o mouse) */
  button:hover, 
  .btn:hover, 
  .rbx-btn-primary:hover, 
  .rbx-btn-secondary:hover,
  .btn-common:hover,
  .btn-control:hover,
  .action-button:hover,
  .menu-button:hover,
  .nav-button:hover,
  .game-button:hover,
  .pagination-button:hover,
  .btn-generic:hover,
  .theme-btn:hover,
  .modal-button:hover,
  .confirm-btn:hover,
  .cancel-btn:hover {
    background-color: #ffcfe1 !important; /* rosa mais claro */
    color: #fff !important;
  }

  /* ? Chat */
  .chat-container, .chat-window, .chat-message {
    background-color: rgba(255, 235, 245, 0.8) !important;
    color: #333 !important;
  }

  /* ? Cartões de jogo */
  .game-card, .game-card-container, .thumbnail-2d-container, 
  .game-card-thumb-container, .game-card-thumb {
    background: rgba(255, 255, 255, 0.7) !important;
    border-radius: 10px !important;
  }
}
